class Solution {
    public long countSubarrays(int[] nums,long k){
        long sum=0,answer=0;
        int left=0;
        for(int right=0;right<nums.length;right++){
            sum+=nums[right];
            while(left<=right&&sum*(right-left+1)>=k)sum-=nums[left++];
            answer+=right-left+1;
        }
        return answer;
    }
}

